// Homepage only: drop Rank Math's own Organization so it doesn't conflict with the
// MedicalOrganization above (both use @id https://healthexpressuc.com/#organization).
// Rank Math's WebSite/WebPage still point to #organization, which now resolves to it.
add_filter( 'rank_math/json_ld', function ( $data ) {
	if ( is_front_page() && isset( $data['publisher'] ) ) {
		unset( $data['publisher'] );
	}
	return $data;
}, 99 );
